// Golden tests for the Java-collection emulation, HashList, stacks and NearestItem.
// Goldens generated by tools/fixtures/core/collections.js from the reference JS implementation.
import Foundation
import ORIPACore

private struct CollectionsFixture: Decodable {
    struct AfterClear: Decodable {
        let size: Int
        let isEmpty: Int
        let values: [[Double]]?
    }

    struct SetJSON: Decodable {
        let addResults: [Int]
        let duplicateAdds: [Int]
        let sizeAfterAdds: Int
        let valuesAfterAdds: [[Double]]
        let contains: [Int]
        let removeExisting: Int
        let removeMissing: Int
        let sizeAfterRemove: Int
        let valuesAfterRemove: [[Double]]
        let valuesAfterReAdd: [[Double]]
        let isEmpty: Int
        let afterClear: AfterClear
        let lineValues: LineValues

        struct LineValues: Decodable {
            let size: Int
            let values: [[Double]]
        }
    }

    struct LinkedSetJSON: Decodable {
        let size: Int
        let values: [[Double]]
        let duplicateAdd: Int
        let contains: Int
        let removeExisting: Int
        let valuesAfterRemove: [[Double]]
        let addAfterRemove: Int
        let valuesAfterReAdd: [[Double]]
        let afterClear: AfterClear
    }

    struct MapJSON: Decodable {
        struct Entry: Decodable {
            let key: [Double]
            let value: String
        }

        let firstOld: String?
        let overwriteOld: String?
        let size: Int
        let getExisting: String?
        let getMissing: String?
        let containsKeys: [Int]
        let keys: [[Double]]
        let values: [String]
        let entries: [Entry]
        let removeExisting: String?
        let removeMissing: String?
        let sizeAfterRemove: Int
        let valuesAfterRemove: [String]
        let afterClear: MapAfterClear

        struct MapAfterClear: Decodable {
            let size: Int
            let isEmpty: Int
        }
    }

    struct HashListJSON: Decodable {
        struct RemoveLast: Decodable {
            let removed: [Double]
            let list: [[Double]]
        }

        struct InsertAt: Decodable {
            let list: [[Double]]
            let indexOfLast: Int
        }

        let adds: [Int]
        let duplicateAdd: Int
        let size: Int
        let list: [[Double]]
        let contains: [Int]
        let indexes: [Int]
        let nextIndexes: [Int]
        let prevIndexes: [Int]
        let getElement: [Double]
        let getNext: [Double]?
        let getPrev: [Double]
        let missingThrows: [Int]
        let sorted: [[Double]]
        let removed: [[Double]]
        let removeLast: RemoveLast
        let insertAt: InsertAt
    }

    struct FixedStackJSON: Decodable {
        struct WithTwo: Decodable {
            let peeked: String
            let pop: String
        }

        let maxSize: Int
        let iterator: [Int]
        let sizeAfterPushes: Int
        let pops: [Int]
        let emptyAfterDrain: Int
        let peekThrows: Int
        let popThrows: Int
        let withTwo: WithTwo
    }

    struct SimpleStackJSON: Decodable {
        let iterator: [Int]
        let peek: Int
        let pops: [Int]
        let isEmpty: Int
        let popThrows: Int
    }

    struct NearestItemJSON: Decodable {
        let defaultItem: [Double]?
        let defaultDistance: Double
        let customItem: [Double]?
        let customDistance: Double
    }

    let set: SetJSON
    let linkedSet: LinkedSetJSON
    let map: MapJSON
    let hashList: HashListJSON
    let fixedStack: FixedStackJSON
    let simpleStack: SimpleStackJSON
    let nearestItem: NearestItemJSON
}

private func oriPoint(_ values: [Double]) -> OriPoint { CoreModelJSON.oriPoint(values) }
private func line(_ values: [Double]) -> OriLine { CoreModelJSON.line(values) }
private func points(_ values: [[Double]]) -> [[Double]] {
    values.map { [Double]($0.prefix(2)) }
}

enum CollectionsTests {
    static var all: [TestSuite] {
        [TestSuite("CoreModel.Collections") { harness in
            let fixture = try Fixtures.decode(CollectionsFixture.self, "Fixtures/core/collections.json")

            // MARK: JavaSet value semantics + reference bucket iteration order
            let set = JavaSet<OriPoint>()
            let setInput = [[0.0, 0.0], [10, 0], [0, 10], [5, 5], [-5, 7]]
            for (index, values) in setInput.enumerated() {
                harness.expectEqual(boolValue(set.add(oriPoint(values))), fixture.set.addResults[index],
                                    "set add[\(index)]")
            }
            let duplicateInputs = [[0.0, 0.0], [5, 5], [1, 1]]
            for (index, values) in duplicateInputs.enumerated() {
                harness.expectEqual(boolValue(set.add(oriPoint(values))), fixture.set.duplicateAdds[index],
                                    "set duplicate add[\(index)]")
            }
            harness.expectEqual(set.size(), fixture.set.sizeAfterAdds, "set size")
            expectEqualArray(harness, set.values().map { CoreModelJSON.pointValues($0) },
                             fixture.set.valuesAfterAdds, "set values")
            let containsInputs = [[0.0, 0.0], [0, 10], [1, 1]]
            for (index, values) in containsInputs.enumerated() {
                harness.expectEqual(boolValue(set.contains(oriPoint(values))), fixture.set.contains[index],
                                    "set contains[\(index)]")
            }
            harness.expectEqual(boolValue(set.remove(oriPoint([0, 0]))), fixture.set.removeExisting, "set remove existing")
            harness.expectEqual(boolValue(set.remove(oriPoint([99, 99]))), fixture.set.removeMissing, "set remove missing")
            harness.expectEqual(set.size(), fixture.set.sizeAfterRemove, "set size after remove")
            expectEqualArray(harness, set.values().map { CoreModelJSON.pointValues($0) },
                             fixture.set.valuesAfterRemove, "set values after remove")
            _ = set.add(oriPoint([0, 0]))
            expectEqualArray(harness, set.values().map { CoreModelJSON.pointValues($0) },
                             fixture.set.valuesAfterReAdd, "set values after re-add")
            harness.expectEqual(boolValue(set.isEmpty()), fixture.set.isEmpty, "set isEmpty")
            set.clear()
            harness.expectEqual(set.size(), fixture.set.afterClear.size, "set clear size")
            harness.expectEqual(boolValue(set.isEmpty()), fixture.set.afterClear.isEmpty, "set clear isEmpty")

            // JavaSet<OriLine>: equal lines dedupe (constructor normalizes endpoint order)
            let lineSet = JavaSet<OriLine>()
            lineSet.add(line([0, 0, 10, 0, 2]))
            lineSet.add(line([0, 0, 10, 0, 2]))
            lineSet.add(line([0, 10, 10, 10, 2]))
            lineSet.add(line([10, 0, 0, 0, 2]))
            harness.expectEqual(lineSet.size(), fixture.set.lineValues.size, "line set size")
            expectEqualArray(harness, lineSet.values().map { CoreModelJSON.lineValues($0) },
                             fixture.set.lineValues.values, "line set values")

            // MARK: JavaLinkedSet insertion order
            let linked = JavaLinkedSet<OriPoint>()
            for values in [[0.0, 0.0], [10, 0], [0, 10], [5, 5]] {
                linked.add(oriPoint(values))
            }
            linked.add(oriPoint([0, 0]))
            harness.expectEqual(linked.size(), fixture.linkedSet.size, "linked size")
            expectEqualArray(harness, linked.values().map { CoreModelJSON.pointValues($0) },
                             fixture.linkedSet.values, "linked values")
            harness.expectEqual(boolValue(linked.add(oriPoint([10, 0]))), fixture.linkedSet.duplicateAdd,
                                "linked duplicate add")
            harness.expectEqual(boolValue(linked.contains(oriPoint([5, 5]))), fixture.linkedSet.contains,
                                "linked contains")
            harness.expectEqual(boolValue(linked.remove(oriPoint([10, 0]))), fixture.linkedSet.removeExisting,
                                "linked remove")
            expectEqualArray(harness, linked.values().map { CoreModelJSON.pointValues($0) },
                             fixture.linkedSet.valuesAfterRemove, "linked values after remove")
            harness.expectEqual(boolValue(linked.add(oriPoint([10, 0]))), fixture.linkedSet.addAfterRemove,
                                "linked re-add")
            expectEqualArray(harness, linked.values().map { CoreModelJSON.pointValues($0) },
                             fixture.linkedSet.valuesAfterReAdd, "linked values after re-add")
            linked.clear()
            harness.expectEqual(linked.size(), fixture.linkedSet.afterClear.size, "linked clear size")
            harness.expectEqual(boolValue(linked.isEmpty()), fixture.linkedSet.afterClear.isEmpty,
                                "linked clear isEmpty")

            // MARK: JavaMap
            let map = JavaMap<OriPoint, String>()
            harness.expectNil(map.put(oriPoint([0, 0]), "origin"), "map first put old")
            map.put(oriPoint([10, 0]), "east")
            map.put(oriPoint([0, 10]), "north")
            harness.expectEqual(map.put(oriPoint([0, 0]), "origin2"), fixture.map.overwriteOld, "map overwrite old")
            harness.expectEqual(map.size(), fixture.map.size, "map size")
            harness.expectEqual(map.get(oriPoint([0, 0])), fixture.map.getExisting, "map get existing")
            harness.expectEqual(map.get(oriPoint([7, 7])), fixture.map.getMissing, "map get missing")
            let containsKeys = [map.containsKey(oriPoint([10, 0])), map.containsKey(oriPoint([3, 3]))]
            expectEqualArray(harness, containsKeys.map(boolValue), fixture.map.containsKeys, "map containsKey")
            expectEqualArray(harness, map.keySet().map { CoreModelJSON.pointValues($0) }, fixture.map.keys,
                             "map keys")
            harness.expectEqual(map.values(), fixture.map.values, "map values")
            let entries = map.entries()
            harness.expectEqual(entries.count, fixture.map.entries.count, "map entries count")
            for index in 0..<min(entries.count, fixture.map.entries.count) {
                expectEqualArray(harness, CoreModelJSON.pointValues(entries[index].key),
                                 fixture.map.entries[index].key, "map entry key[\(index)]")
                harness.expectEqual(entries[index].value, fixture.map.entries[index].value,
                                    "map entry value[\(index)]")
            }
            harness.expectEqual(map.remove(oriPoint([10, 0])), fixture.map.removeExisting, "map remove existing")
            harness.expectEqual(map.remove(oriPoint([10, 0])), fixture.map.removeMissing, "map remove missing")
            harness.expectEqual(map.size(), fixture.map.sizeAfterRemove, "map size after remove")
            harness.expectEqual(map.values(), fixture.map.valuesAfterRemove, "map values after remove")
            map.clear()
            harness.expectEqual(map.size(), fixture.map.afterClear.size, "map clear size")
            harness.expectEqual(boolValue(map.isEmpty()), fixture.map.afterClear.isEmpty, "map clear isEmpty")

            // MARK: HashList
            let list = HashList<OriLine>()
            let listLines = [
                line([30, 0, 40, 0, 2]), line([10, 0, 20, 0, 2]),
                line([20, 0, 25, 0, 2]), line([50, 0, 60, 0, 2]),
            ]
            for (index, element) in listLines.enumerated() {
                harness.expectEqual(boolValue(list.add(element)), fixture.hashList.adds[index],
                                    "hashList add[\(index)]")
            }
            harness.expectEqual(boolValue(list.add(line([30, 0, 40, 0, 2]))), fixture.hashList.duplicateAdd,
                                "hashList duplicate add")
            harness.expectEqual(list.size(), fixture.hashList.size, "hashList size")
            expectEqualArray(harness, list.getList().map { CoreModelJSON.lineValues($0) },
                             fixture.hashList.list, "hashList list")
            let listContains = [list.contains(listLines[1]), list.contains(line([0, 0, 1, 0, 2]))]
            expectEqualArray(harness, listContains.map(boolValue), fixture.hashList.contains, "hashList contains")
            for index in 0..<listLines.count {
                harness.expectEqual(try? list.getIndex(listLines[index]), fixture.hashList.indexes[index],
                                    "hashList getIndex[\(index)]")
                harness.expectEqual(try? list.getNextIndex(listLines[index]), fixture.hashList.nextIndexes[index],
                                    "hashList getNextIndex[\(index)]")
                harness.expectEqual(try? list.getPrevIndex(listLines[index]), fixture.hashList.prevIndexes[index],
                                    "hashList getPrevIndex[\(index)]")
            }
            expectEqualArray(harness, CoreModelJSON.lineValues(try list.getElement(listLines[2])),
                             fixture.hashList.getElement, "hashList getElement")
            let nextLine = try? list.getNext(listLines[0])
            harness.expectEqual(nextLine.flatMap { CoreModelJSON.lineValues($0) },
                                fixture.hashList.getNext, "hashList getNext")
            harness.expectEqual(CoreModelJSON.lineValues(try list.getPrev(listLines[0])!),
                                fixture.hashList.getPrev, "hashList getPrev")
            let missing = line([0, 0, 1, 1, 2])
            let throwResults = [
                doesThrow { _ = try list.getIndex(missing) },
                doesThrow { _ = try list.getElement(missing) },
                doesThrow { _ = try list.getNextIndex(missing) },
                doesThrow { _ = try list.getPrevIndex(missing) },
                doesThrow { try list.remove(missing) },
            ]
            expectEqualArray(harness, throwResults.map(boolValue), fixture.hashList.missingThrows,
                             "hashList missing throws")
            list.sort { $0.start.x < $1.start.x ? -1 : ($0.start.x > $1.start.x ? 1 : 0) }
            expectEqualArray(harness, list.getList().map { CoreModelJSON.lineValues($0) },
                             fixture.hashList.sorted, "hashList sorted")
            try list.remove(listLines[1])
            expectEqualArray(harness, list.getList().map { CoreModelJSON.lineValues($0) },
                             fixture.hashList.removed, "hashList removed")
            harness.expectEqual(CoreModelJSON.lineValues(list.removeLast()!), fixture.hashList.removeLast.removed,
                                "hashList removeLast removed")
            expectEqualArray(harness, list.getList().map { CoreModelJSON.lineValues($0) },
                             fixture.hashList.removeLast.list, "hashList removeLast list")
            let insertList = HashList<OriLine>()
            insertList.add(line([0, 0, 1, 0, 2]))
            insertList.add(line([2, 0, 3, 0, 2]))
            insertList.add(1, line([1, 0, 2, 0, 2]))
            expectEqualArray(harness, insertList.getList().map { CoreModelJSON.lineValues($0) },
                             fixture.hashList.insertAt.list, "hashList insertAt list")
            harness.expectEqual(try? insertList.getIndex(line([2, 0, 3, 0, 2])),
                                fixture.hashList.insertAt.indexOfLast, "hashList insertAt index")

            // MARK: FixedStack (bounded, drops oldest)
            let fixed = FixedStack<Int>(fixture.fixedStack.maxSize)
            harness.expectEqual(fixed.maxSize(), fixture.fixedStack.maxSize, "fixed maxSize")
            for value in 0..<8 { fixed.push(value) }
            harness.expectEqual(fixed.size(), fixture.fixedStack.sizeAfterPushes, "fixed size")
            var fixedIterator: [Int] = []
            let fixedNodeIterator = fixed.iterator()
            while fixedNodeIterator.hasNext() { fixedIterator.append(fixedNodeIterator.next()) }
            expectEqualArray(harness, fixedIterator, fixture.fixedStack.iterator, "fixed iterator")
            var fixedPops: [Int] = []
            while !fixed.isEmpty() {
                if let value = try? fixed.pop() { fixedPops.append(value) }
            }
            expectEqualArray(harness, fixedPops, fixture.fixedStack.pops, "fixed pops")
            harness.expectEqual(boolValue(fixed.isEmpty()), fixture.fixedStack.emptyAfterDrain, "fixed empty")
            harness.expectEqual(boolValue(doesThrow { _ = try fixed.peek() }), fixture.fixedStack.peekThrows,
                                "fixed peek throws")
            harness.expectEqual(boolValue(doesThrow { _ = try fixed.pop() }), fixture.fixedStack.popThrows,
                                "fixed pop throws")
            let fixedTwo = FixedStack<String>(2)
            fixedTwo.push("a")
            fixedTwo.push("b")
            fixedTwo.push("c")
            harness.expectEqual(try? fixedTwo.peek(), fixture.fixedStack.withTwo.peeked, "fixedTwo peek")
            harness.expectEqual(try? fixedTwo.pop(), fixture.fixedStack.withTwo.pop, "fixedTwo pop")

            // MARK: SimpleStack
            let simple = SimpleStack<Int>()
            simple.push(1)
            simple.push(2)
            simple.push(3)
            var simpleIterator: [Int] = []
            let simpleNodeIterator = simple.iterator()
            while simpleNodeIterator.hasNext() { simpleIterator.append(simpleNodeIterator.next()) }
            expectEqualArray(harness, simpleIterator, fixture.simpleStack.iterator, "simple iterator")
            harness.expectEqual(try? simple.peek(), fixture.simpleStack.peek, "simple peek")
            let simplePops: [Int?] = [try? simple.pop(), try? simple.pop(), try? simple.pop()]
            expectEqualArray(harness, simplePops, fixture.simpleStack.pops.map { Optional($0) }, "simple pops")
            harness.expectEqual(boolValue(simple.isEmpty()), fixture.simpleStack.isEmpty, "simple isEmpty")
            harness.expectEqual(boolValue(doesThrow { _ = try simple.pop() }), fixture.simpleStack.popThrows,
                                "simple pop throws")

            // MARK: NearestItem
            let defaultNearest = NearestItem<OriPoint>()
            harness.expectNil(defaultNearest.nearestItem, "nearest default item")
            harness.expectEqual(defaultNearest.distance, fixture.nearestItem.defaultDistance, "nearest default distance")
            let customNearest = NearestItem<OriPoint>(oriPoint([3, 4]), 5.0)
            expectEqualArray(harness, CoreModelJSON.pointValues(customNearest.nearestItem!), fixture.nearestItem.customItem!,
                             "nearest custom item")
            harness.expectEqual(customNearest.distance, fixture.nearestItem.customDistance, "nearest custom distance")
        }]
    }
}
